        c = _c;
    }

    function run(address newCeo, uint256 seedAmount) public payable {
        require(newCeo != address(0), "newCeo must not be zero address");
        require(msg.sender == newCeo, "caller must match newCeo parameter");

        uint256 marketDrugsBefore = c.marketDrugs();
        uint256 balanceBefore = address(c).balance;
        address ceoBefore = c.ceoAddress();
        require(ceoBefore == msg.sender, "only current CEO can call DrugDealer");

        c.DrugDealer();

        assert(c.ceoAddress() == msg.sender);
    }

    receive() external payable {}
}
